// Gathers what the pure renderer needs (state, git, liveness) and renders. The daemon calls
// renderPage for every GET and only ever sends the result; the CLI's `render` also writes the
// static file:// copy, which is the one generated file, and keeps it out of git.
import { closeSync, fsyncSync, openSync, readFileSync, renameSync, unlinkSync, writeFileSync, writeSync } from "node:fs";
import { basename, relative } from "node:path";
import { appPorts } from "./app.mjs";
import { gitContext } from "./git.mjs";
import { buildId, checkoutFile, git } from "./paths.mjs";
import { render } from "./render.mjs";
import { applyRequests, roadmapView } from "./roadmap.mjs";
import { loadState } from "./state.mjs";

export function roadmapOverlay(root, requests) {
  try {
    return applyRequests(roadmapView(root), requests);
  } catch (err) {
    return { source: null, readAt: new Date().toISOString(), error: `the roadmap couldn't be read: ${err.message}`, sections: [], unmatched: [] };
  }
}

export async function renderPage(co, loc, srv = {}) {
  const { state } = await loadState(loc.statePath);
  // For render only, never written back: the repo's roadmap with the owner's open requests on it.
  state._roadmap = roadmapOverlay(co.root, state.roadmapRequests);
  const repo = state.repo || basename(co.root);
  // The page's own daemon also listens from inside the checkout; it's not the app.
  let ownPort = null;
  try {
    ownPort = Number(readFileSync(checkoutFile(co, "build-status.port"), "utf8").trim()) || null;
  } catch {}
  const app = await appPorts(co.root, repo, { exclude: [srv.port, ownPort].filter(Boolean) });
  const out = render(state, {
    title: repo,
    live: Boolean(srv.live),
    port: srv.port ?? null,
    reason: srv.reason || "",
    build: buildId(),
    git: gitContext(co.root),
    app,
  });
  const summary = {
    repo: state.repo || basename(co.root),
    done: out.done,
    total: out.total,
    gate: out.gate,
    findings: out.findings,
    openQuestions: out.openQuestions,
    draft: Boolean(state.extra.draft),
  };
  return { html: out.html, summary };
}

function ensureIgnored(co, htmlPath) {
  if (!co.isGit) return;
  const rel = relative(co.root, htmlPath);
  if (git(co.root, ["check-ignore", "-q", rel]) !== null) return; // already ignored
  const gi = `${co.root}/.gitignore`;
  let cur = "";
  try {
    cur = readFileSync(gi, "utf8");
  } catch {}
  writeFileSync(gi, `${cur}${cur && !cur.endsWith("\n") ? "\n" : ""}${cur ? "\n" : ""}# Local build status view (generated by build-status)\n${rel}\n`);
}

export async function writeStaticHtml(co, loc, srv = {}) {
  const { html, summary } = await renderPage(co, loc, srv);
  // temp in the git dir (never shows in git status), renamed into place
  const tmp = checkoutFile(co, `build-status.html.tmp.${process.pid}`);
  const fd = openSync(tmp, "w");
  try {
    writeSync(fd, html);
    fsyncSync(fd);
  } finally {
    closeSync(fd);
  }
  try {
    renameSync(tmp, loc.htmlPath);
  } catch (err) {
    unlinkSync(tmp);
    if (err.code !== "EXDEV") throw err;
    writeFileSync(loc.htmlPath, html);
  }
  ensureIgnored(co, loc.htmlPath);
  return { htmlPath: loc.htmlPath, summary };
}
